//! The generated roots index — the registry read side's fast
//! path (plan §3.2's generator story: the phf artifact derived
//! from the committed rows, consumed by `registry::lookup` and
//! `registry::lookup_detailed`).
//!
//! GENERATED by `cargo xtask gen-tables` from `crate::rows::ROWS` —
//! DO NOT EDIT. The committed bytes are pinned equal to the
//! regeneration in `tests/codegen.rs`, and `cargo xtask
//! verify-tables` is the same check from the CLI side; a row edit
//! that forgets the regeneration fails `cargo test` first.
//!
//! The semantics the read side keeps: this module answers WHICH
//! root a utility body addresses — the longest dash-aligned prefix
//! that is a root (the registry's own `body_matches_root` rule:
//! exact, or `root` + `-`) — and hands back that root's row
//! indices in registry order. The per-row shape contract
//! (`ValueKind::accepts`) stays in `registry.rs`, as does the
//! pre-index linear scan (`registry::lookup_linear`), kept as the
//! documented differential oracle the tests and the lookup bench
//! battery the index against.

/// The hash seed the generator settled on (the lowest seed whose
/// open-addressed placement keeps every displacement under the
/// probe bound) — a function of the rows, byte-stable.
pub const PHF_SEED: u32 = 0;

/// The slot count: three times the distinct roots, rounded up to
/// the next power of two (the mask arithmetic needs it).
pub const SLOTS: usize = 512;

/// The slot-table mask (`SLOTS - 1`).
pub const MASK: usize = 511;

/// The sentinel an empty slot carries.
pub const EMPTY: u16 = u16::MAX;

/// The worst-case probe walk (the generator's maximum displacement
/// plus one): every indexed root is reachable within this many
/// steps, and a miss terminates at the first empty slot it meets.
pub const PROBE_BOUND: usize = 4;

/// One indexed root: the root text and the row indices that carry
/// it, in registry order (the shape `registry::lookup` walks).
#[derive(Clone, Copy, Debug)]
pub struct IndexEntry {
    /// The root text (the longest-prefix probe's match key).
    pub root: &'static str,
    /// The row indices under this root, ascending — the same
    /// order the pre-index linear scan returned.
    pub rows: &'static [u16],
}

