/// Seeded FNV-1a (32-bit) — the SAME function the generator's seed
/// search used, embedded verbatim so runtime and generation agree
/// by construction (the drift pins cover the constants; this is
/// the hash itself).
pub const fn fnv1a(seed: u32, text: &str) -> u32 {
    let mut hash = 0x811c_9dc5u32 ^ seed;
    let bytes = text.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        hash ^= bytes[i] as u32;
        hash = hash.wrapping_mul(0x0100_0193);
        i += 1;
    }
    hash
}

/// The hash slot a root starts its probe at (the mask arithmetic
/// the slot table was generated for).
pub fn slot_of(root: &str) -> usize {
    (fnv1a(PHF_SEED, root) as usize) & MASK
}

/// The longest dash-aligned prefix of `body` that is a root — the
/// read side's winner (the registry's `body_matches_root` rule is
/// exactly `root == body || body[root.len()] == b'-'`, which makes
/// every matching root a dash-aligned prefix, so the FIRST hit
/// longest-first is the longest-prefix winner). The probe walks
/// the slot table from the hash slot and stops at the first empty
/// slot or `PROBE_BOUND` — whichever comes first.
pub fn longest_prefix(body: &str) -> Option<&'static IndexEntry> {
    let mut end = body.len();
    loop {
        if let Some(entry) = probe(&body[..end]) {
            return Some(entry);
        }
        // The next shorter dash-aligned prefix: drop the last `-`
        // and everything after it (`inset-x-2` → `inset-x` →
        // `inset`). The empty prefix is never a root (the row
        // invariants pin non-empty roots), so one miss past the
        // last dash ends the walk.
        end = body[..end].rfind('-')?;
    }
}

/// The slot-table probe for one candidate root text: walk from the
/// hash slot, stop on an exact-text hit, an empty slot, or the
/// probe bound.
fn probe(candidate: &str) -> Option<&'static IndexEntry> {
    let start = (fnv1a(PHF_SEED, candidate) as usize) & MASK;
    for step in 0..PROBE_BOUND {
        let occupant = ROOT_SLOTS[(start + step) & MASK];
        if occupant == EMPTY {
            return None;
        }
        let entry = &ROOT_ENTRIES[occupant as usize];
        if entry.root == candidate {
            return Some(entry);
        }
    }
    None
}
